      }
    ],
    "h_statements": [
      {
        "code": "H225",
        "text": "고인화성 액체 및 증기",
        "line": "p2:L5"
      },
      {
        "code": "H304",
        "text": "삼켜서 기도로 유입되면 치명적일 수 있음",
        "line": "p2:L6"
      },
      {
        "code": "H315",
        "text": "피부에 자극을 일으킴",
        "line": "p2:L7"
      },
      {
        "code": "H332",
        "text": "흡입하면 유해함",
        "line": "p2:L8"
      },
      {
        "code": "H335",
        "text": "호흡기계 자극을 일으킬 수 있음",
        "line": "p2:L9"
      },
      {
        "code": "H340",
        "text": "유전적인 결함을 일으킬 수 있음",
        "line": "p2:L10"
      },
      {
        "code": "H351",
        "text": "암을 일으킬 것으로 의심됨",
        "line": "p2:L11"
      },
      {
        "code": "H370",
        "text": "신체 중 장기에 손상을 일으킴",
        "line": "p2:L12"
      },
      {
        "code": "H411",
        "text": "장기적인 영향에 의해 수생생물에게 유독함",
        "line": "p2:L13"
      }
    ],
    "p_statements": [
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p2:L16"
      },
      {
        "code": "P210",
        "type": "예방",
        "text": "열•스파크•화염•고열로부터 멀리하시오 - 금연",
        "line": "p2:L17"
      },
      {
        "code": "P233",
        "type": "예방",
        "text": "물과 접촉하지 않게 하시오.",
        "line": "p2:L18"
      },
      {
        "code": "P240",
        "type": "예방",
        "text": "용기와 수용설비를 접합시키거나 접지하시오.",
        "line": "p2:L19"
      },
      {
        "code": "P241",
        "type": "예방",
        "text": "폭발 방지용 전기•환기•조명 장비를 사용하시오.",
        "line": "p2:L20"
      },
      {
        "code": "P242",
        "type": "예방",
        "text": "스파크가 발생하지 않는 도구만을 사용하시오.",
        "line": "p2:L21"
      },
      {
        "code": "P243",
        "type": "예방",
        "text": "정전기 방지 조치를 취하시오.",
        "line": "p2:L22"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑•보호의•보안경•안면보호구를 착용하시오.",
        "line": "p2:L23"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 취급 부위를 철저히 씻으시오.",
        "line": "p2:L24"
      },
      {
        "code": "P201",
        "type": "예방",
        "text": "사용 전 취급 설명서를 확보하시오.",
        "line": "p2:L25"
      },
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p2:L26"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "물과 접촉 시 자연발화 가능한 인화성 가스를 발생시킴",
        "line": "p2:L27"
      },
      {
        "code": "P270",
        "type": "예방",
        "text": "화재를 일으키거나 강렬하게 함: 산화제",
        "line": "p2:L28"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p2:L29"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부 또는 머리카락에 묻으면 오염된 모든 의복을 즉시 벗으시오.",
        "line": "p2:L31"
      },
      {
        "code": "P370+P378",
        "type": "대응",
        "text": "화재 시 불을 끄기 위해 소화기를 사용하시오.",
        "line": "p2:L32"
      },
      {
        "code": "P302+P352",
        "type": "대응",
        "text": "피부에 묻으면 다량의 물/비누로 씻으시오.",
        "line": "p3:L2"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "의학적 처치를 하시오",
        "line": "p3:L3"
      },
      {
        "code": "P332+P313",
        "type": "대응",
        "text": "피부 자극이 생기면",
        "line": "p3:L4"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된 의복을 벗으시오. 다시 사용전 세척하시오.",
        "line": "p3:L5"
      },
      {
        "code": "P308+P313",
        "type": "대응",
        "text": "노출되거나 노출이 우려되면 의학적인 조치•조언을 구하시오.",
        "line": "p3:L6"
      },
      {
        "code": "P301+P310",
        "type": "대응",
        "text": "삼켰다면 즉시 의료기관의 진찰을 받으시오.",
        "line": "p3:L7"
      },
      {
        "code": "P331",
        "type": "대응",
        "text": "토하게 하지 마시오.",
        "line": "p3:L8"
      },
      {
        "code": "P308+P311",
        "type": "대응",
        "text": "노출 또는 노출이 우려되면, 의료기관의 진찰을 받으시오.",
        "line": "p3:L9"
      },
      {
        "code": "P391",
        "type": "대응",
        "text": "누출물을 모으시오.",
        "line": "p3:L10"
      },
      {
        "code": "P403+P235",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하고 저온으로 유지하시오",
        "line": "p3:L12"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오.",
        "line": "p3:L13"
      },
      {
        "code": "P391",
        "type": "저장",
        "text": "누출물을 모으시오.",
        "line": "p3:L14"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "관련 법규에 명시된 내용에 따라 내용물 용기를 폐기하시오.",
        "line": "p3:L16"
      }
    ],
